import { fireEvent, render, screen, waitFor, within } from '@testing-library/preact';
import { loadFixture } from 'rimstudio-testkit';
import type { ConvertScanDto } from 'rimstudio-ipc-types';
import { describe, expect, it } from 'vitest';
import { DetailPane } from './DetailPane';
import { removal } from './removeStore';
import { installTransport, openFixtureProject } from './testSupport';

const [first] = loadFixture<ConvertScanDto>('designer_convert_scan').candidates;
if (!first) throw new Error('fixture');
// the converted mod: the first weapon was generated by RimStudio, the others are written by hand
const [generated, byHand] = loadFixture<ConvertScanDto>('patches-scan-converted').candidates;
if (!generated || !byHand) throw new Error('fixture');

describe('DetailPane', () => {
  it('shows what the scan knows and opens on the questions of a convertible weapon', () => {
    installTransport();
    const p = openFixtureProject();
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={first}
        familySize={3}
      />,
    );
    expect(screen.getByRole('heading', { name: 'Gewehr 41 (m)' })).toBeTruthy();
    expect(screen.getByText('Bullet_MauserRifle')).toBeTruthy();
    expect(screen.getByRole('tab', { name: /Questions/ }).getAttribute('aria-selected')).toBe(
      'true',
    );
    expect(screen.getByText('0 of 9 answered')).toBeTruthy();
  });

  it('lists what is missing on the other tabs and jumps to the question from there', async () => {
    installTransport();
    const p = openFixtureProject();
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={first}
        familySize={1}
      />,
    );
    // on the questions tab the form itself is the list
    expect(screen.queryByRole('region', { name: /answers are missing/ })).toBeNull();
    fireEvent.click(screen.getByRole('tab', { name: 'Definition' }));
    const list = await screen.findByRole('region', { name: /9 answers are missing/ });
    expect(list.textContent).toContain('Which caliber (ammo set) does the weapon use?');
    fireEvent.click(within(list).getAllByRole('button', { name: 'Answer' })[0] as HTMLElement);
    expect(screen.getByRole('tab', { name: /Questions/ }).getAttribute('aria-selected')).toBe(
      'true',
    );
  });

  it('shows the definition file on its tab', async () => {
    installTransport();
    const p = openFixtureProject();
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={first}
        familySize={1}
      />,
    );
    fireEvent.click(screen.getByRole('tab', { name: 'Definition' }));
    expect(await screen.findByRole('region', { name: /Text of Defs/ })).toBeTruthy();
  });

  it('has no questions or plan for a weapon that cannot be converted', () => {
    installTransport();
    const p = openFixtureProject();
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={{
          ...first,
          status: 'unsupported-kind',
          reason: 'a weapon with a beam verb and no projectile',
          asks: [],
        }}
        familySize={1}
      />,
    );
    expect(screen.queryByRole('tab', { name: /Questions/ })).toBeNull();
    expect(screen.queryByRole('tab', { name: 'Plan' })).toBeNull();
    expect(screen.getByText('a weapon with a beam verb and no projectile')).toBeTruthy();
  });
  it('shows where the conversion of an already converted weapon comes from and how to remove it', async () => {
    installTransport();
    const p = openFixtureProject('patches-project-converted');
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={generated}
        familySize={1}
      />,
    );
    const card = screen.getByRole('region', { name: 'Existing conversion' });
    expect(within(card).getByText('Generated by RimStudio.')).toBeTruthy();
    // the update mode of the plan stays where it was
    expect(screen.getByRole('tab', { name: 'Plan' }).getAttribute('aria-selected')).toBe('true');
    expect(screen.queryByRole('tab', { name: /Questions/ })).toBeNull();
    fireEvent.click(within(card).getByRole('button', { name: 'Replace patch' }));
    await waitFor(() => expect(removal.value.phase).toBe('review'));
    expect(removal.value).toMatchObject({ target: { defName: 'OH_G41m', mode: 'replace' } });
  });

  it('opens the removal of the weapon from the remove button', async () => {
    installTransport();
    const p = openFixtureProject('patches-project-converted');
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={generated}
        familySize={1}
      />,
    );
    fireEvent.click(screen.getByRole('button', { name: 'Remove patch' }));
    await waitFor(() => expect(removal.value.phase).toBe('review'));
    expect(removal.value).toMatchObject({ target: { defName: 'OH_G41m', mode: 'remove' } });
  });

  it('says why a patch written by hand cannot be removed and keeps the plan tab', () => {
    installTransport();
    const p = openFixtureProject('patches-project-converted');
    render(
      <DetailPane
        project={{ projectId: p.projectId, path: p.path, name: p.name }}
        candidate={byHand}
        familySize={1}
      />,
    );
    const card = screen.getByRole('region', { name: 'Existing conversion' });
    expect(within(card).getByText('Written by hand in this mod.')).toBeTruthy();
    expect(within(card).getByText(/never changed here/)).toBeTruthy();
    expect(within(card).queryByRole('button')).toBeNull();
    expect(screen.getByRole('tab', { name: 'Plan' })).toBeTruthy();
  });

  it('shows no existing conversion for a weapon that is not converted or has no record of one', () => {
    installTransport();
    const p = openFixtureProject();
    const project = { projectId: p.projectId, path: p.path, name: p.name };
    const view = render(<DetailPane project={project} candidate={first} familySize={1} />);
    expect(screen.queryByRole('region', { name: 'Existing conversion' })).toBeNull();
    view.unmount();
    // a scan of an older build has no `existing` member
    const { existing: _existing, ...legacy } = generated;
    render(<DetailPane project={project} candidate={legacy} familySize={1} />);
    expect(screen.queryByRole('region', { name: 'Existing conversion' })).toBeNull();
    expect(screen.getByText('Already CE')).toBeTruthy();
  });
});
